files.content:
* { box-sizing: border-box; }
[hidden] { display: none !important; }
:root { color-scheme: dark; font-family: system-ui, sans-serif; font-size: 16px; background: #182b35; color: #f6f0dc; }
body { min-width: 360px; min-height: 100vh; margin: 0; background: radial-gradient(ellipse at 50% 42%, #294854 0, #203944 38%, #182b35 78%); }
.page { min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 32px 20px; }
.eyebrow { margin: 0 0 18px; color: #f2b866; font-size: .85rem; font-weight: 800; letter-spacing: .2em; }
.eyebrow span { margin-left: 5px; }
.card { position: relative; width: min(100%, 430px); padding: 20px 24px 18px; overflow: hidden; background: #f6f0dc; color: #20343d; border: 4px solid #10232b; box-shadow: 8px 8px 0 #10232b, 0 22px 55px #0b1a2080; }
.card::before { position: absolute; inset: 7px; border: 2px solid #d8d0b7; content: ""; pointer-events: none; }
.card-top, .card-foot { position: relative; display: flex; justify-content: space-between; align-items: center; font-size: .73rem; font-weight: 800; letter-spacing: .12em; }
.card-top { color: #64747a; }
.online { display: flex; gap: 7px; align-items: center; color: #387a5d; }
.online i { width: 8px; height: 8px; background: #5aab76; box-shadow: 0 0 0 3px #5aab7626; }
.avatar { position: relative; height: 132px; margin: 19px 0 12px; overflow: hidden; background: #a8c9b2; border: 3px solid #20343d; image-rendering: pixelated; }
.avatar::before { position: absolute; right: -5%; bottom: 0; width: 110%; height: 48%; background: #62927b; clip-path: polygon(0 75%, 24% 15%, 45% 65%, 67% 7%, 100% 70%, 100% 100%, 0 100%); content: ""; }
.sun { position: absolute; top: 18px; right: 48px; width: 32px; height: 32px; background: #f2b866; box-shadow: 0 0 0 5px #f2b86630; }
.pixel-person { position: absolute; z-index: 1; bottom: 0; left: 50%; width: 75px; height: 85px; transform: translateX(-50%); background: #df8e63; clip-path: polygon(30% 0, 70% 0, 70% 13%, 83% 13%, 83% 43%, 70% 43%, 70% 56%, 95% 56%, 100% 100%, 0 100%, 5% 56%, 30% 56%, 30% 43%, 17% 43%, 17% 13%, 30% 13%); }
.pixel-person i { position: absolute; top: 27px; left: 19px; width: 7px; height: 7px; background: #20343d; box-shadow: 30px 0 #20343d; }
.identity { text-align: center; }
.editable { cursor: text; outline: 2px solid transparent; outline-offset: 3px; transition: outline-color .15s, background-color .15s; }
.editable:hover { outline-color: #d5b66c; background: #f2ead0; }
.editable:focus { outline-color: #b87b34; background: #fff8e6; }
h1 { display: inline-block; max-width: 100%; margin: 2px 0 4px; overflow-wrap: anywhere; font-size: clamp(1.7rem, 8vw, 2.25rem); line-height: 1.15; }
.title { display: inline-block; margin: 0; color: #54716f; font-weight: 700; }
.divider { display: flex; align-items: center; gap: 12px; margin: 17px 0 14px; color: #c78945; }
.divider::before, .divider::after { height: 2px; flex: 1; background: #d8d0b7; content: ""; }
.bio-wrap label, .bio-meta { color: #718080; font-size: .72rem; font-weight: 800; letter-spacing: .1em; }
.bio { min-height: 70px; margin: 8px 0 8px; padding: 7px; color: #32464a; line-height: 1.55; overflow-wrap: anywhere; }
.bio-meta { display: flex; justify-content: space-between; gap: 12px; font-size: .65rem; }
.actions { display: flex; gap: 10px; margin-top: 18px; }
.button { min-height: 46px; padding: 10px 15px; border: 2px solid #20343d; font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s, box-shadow .12s, background-color .12s; }
.button:hover { transform: translateY(-2px); box-shadow: 0 3px 0 #20343d; }
.button:active { transform: translateY(1px); box-shadow: none; }
.button:focus-visible { outline: 3px solid #b87b34; outline-offset: 3px; }
.secondary { background: transparent; color: #20343d; }
.secondary:hover { background: #e9e1ca; }
.primary { flex: 1; background: #20343d; color: #f6f0dc; }
.primary:hover { background: #31545c; }
.saved { margin: 12px 0 0; color: #387a5d; font-size: .9rem; font-weight: 800; text-align: center; }
.card-foot { margin-top: 17px; padding-top: 12px; color: #9b9887; border-top: 1px solid #d8d0b7; font-size: .63rem; }
.hint { margin: 24px 0 0; color: #c1cfca; font-size: .9rem; text-align: center; }
@media (max-width: 400px) { .page { padding: 24px 16px; } .card { padding-right: 19px; padding-left: 19px; } .avatar { height: 118px; } }

const fields = [
  document.querySelector('#profile-name'),
  document.querySelector('#profile-title'),
  document.querySelector('#profile-bio')
];
const bio = fields[2];
const count = document.querySelector('#char-count');
const savedMessage = document.querySelector('#saved-message');
const saveButton = document.querySelector('#save-button');
const cancelButton = document.querySelector('#cancel-button');
let savedValues = fields.map(field => field.textContent.trim());
const bioLimit = 120;

function updateCount() {
  const value = bio.textContent.slice(0, bioLimit);
  if (bio.textContent !== value) bio.textContent = value;
  count.textContent = `${value.length} / ${bioLimit}`;
}

function hideSaved() {
  savedMessage.hidden = true;
}

bio.addEventListener('input', () => {
  updateCount();
  hideSaved();
});
fields.slice(0, 2).forEach(field => field.addEventListener('input', hideSaved));

fields.forEach(field => field.addEventListener('keydown', event => {
  if (event.key === 'Enter' && field !== bio) {
    event.preventDefault();
    field.blur();
  }
}));

saveButton.addEventListener('click', () => {
  updateCount();
  savedValues = fields.map(field => field.textContent.trim());
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  savedMessage.hidden = false;
});

cancelButton.addEventListener('click', () => {
  fields.forEach((field, index) => { field.textContent = savedValues[index]; });
  updateCount();
  hideSaved();
});

updateCount();
